sql_calls.sql:
SELECT count(*) AS abandoned_baskets 
FROM payments.pos_payments 
WHERE bill_ts >= '2026-06-01' AND bill_ts < '2026-07-01' AND status = 'declined';

SELECT sku, name, pack, case_units, case_kg 
FROM store.products 
WHERE name ILIKE '%atta%' OR pack ILIKE '%5%' OR name ILIKE '%5kg%';

SELECT count(*) AS upi_refunds_june2026
FROM payments.upi_refunds
WHERE requested_ts >= '2026-06-01' AND requested_ts < '2026-07-01';

SELECT sku, name, pack, case_kg 
FROM store.products 
WHERE name ILIKE '%atta%' OR pack ILIKE '%5kg%' OR case_kg = 5;

SELECT COUNT(DISTINCT bill_id) 
FROM payments.pos_payments 
WHERE ts >= '2026-06-01' AND ts < '2026-07-01';

SELECT SUM(net_inr) AS total_net_upi
FROM payments.upi_settlements
WHERE settlement_date >= '2026-06-01' AND settlement_date < '2026-07-01';

SELECT kind, resolution, amount_inr, bill_id 
FROM payments.customer_complaints 
LIMIT 20;
